// Visitor journeys for the CMS-driven campaign navbar item, home banner and
// campaign pages. The CMS is stubbed with the cross-repo golden (generated by
// the CMS repo from its real routes; see src/lib/campaigns.golden.test.tsx for
// how to refresh it), so these specs exercise the real app against the real
// response shape. Every other external request is refused.

import { readFileSync } from "node:fs";

import { expect, test, type Page } from "@playwright/test";

const golden = JSON.parse(readFileSync(new URL("../src/lib/__golden__/christmas-2026.golden.json", import.meta.url), "utf8"));

type Mode = "golden" | "toggles-off" | "api-down";

async function stubCms(page: Page, mode: Mode = "golden") {
  await page.addInitScript(() => {
    try {
      localStorage.setItem("thg_lang", "vi");
    } catch {
      /* storage disabled */
    }
  });
  await page.route("**/api/v1/**", (route) => route.fulfill({ status: 503, contentType: "application/json", body: "{}" }));
  await page.route("**/api/v1/translations**", (route) =>
    route.fulfill({ status: 200, contentType: "application/json", body: JSON.stringify({ locale: "vi", translations: {} }) }),
  );
  if (mode === "api-down") return;
  await page.route("**/api/v1/campaigns**", (route) => {
    const url = new URL(route.request().url());
    const lang = (url.searchParams.get("lang") ?? "vi") as "vi" | "en";
    if (url.pathname.endsWith("/campaigns/christmas-2026")) {
      return route.fulfill({ status: 200, contentType: "application/json", body: JSON.stringify(golden.detail[lang]) });
    }
    const body = structuredClone(golden.list[lang]);
    if (mode === "toggles-off") {
      for (const c of body.campaigns) Object.assign(c, { nav_featured: false, home_featured: false });
    }
    return route.fulfill({ status: 200, contentType: "application/json", body: JSON.stringify(body) });
  });
}

const pill = (page: Page) => page.getByRole("link", { name: /Christmas\s*NEW/ });
const banner = (page: Page) => page.getByRole("region", { name: "Christmas 2026 Collection" });
const overflowX = (page: Page) =>
  page.evaluate(() => document.documentElement.scrollWidth - document.documentElement.clientWidth);

test.describe("desktop (1280px)", () => {
  test.use({ viewport: { width: 1280, height: 800 } });

  test("home: banner and pill; hover opens the mega-menu and an item navigates under /vi", async ({ page }) => {
    await stubCms(page);
    await page.goto("/vi");
    await expect(banner(page)).toBeVisible();
    await expect(banner(page).getByRole("link", { name: /Khám phá bộ sưu tập/ })).toHaveAttribute("href", "/vi/christmas");

    await expect(pill(page)).toBeVisible();
    await pill(page).hover();
    const menu = page.getByRole("navigation", { name: "Danh mục chương trình" });
    await expect(menu).toBeVisible();
    await menu.getByRole("link", { name: /Best Seller/ }).click();
    await expect(page).toHaveURL(/\/vi\/catalog\/best-seller$/);
  });

  test("the pill opens /vi/christmas", async ({ page }) => {
    await stubCms(page);
    await page.goto("/vi");
    await pill(page).click();
    await expect(page).toHaveURL(/\/vi\/christmas$/);
    await expect(page.getByRole("heading", { level: 1 })).toContainText("Christmas");
  });

  for (const mode of ["toggles-off", "api-down"] as const) {
    test(`${mode}: no pill and no banner, and the navbar keeps its height without overflow`, async ({ page }) => {
      await stubCms(page);
      await page.goto("/vi");
      await expect(pill(page)).toBeVisible();
      const header = page.locator("nav").first();
      const withPill = await header.boundingBox();

      const other = await page.context().newPage();
      await stubCms(other, mode);
      // Absence only counts once the campaigns answer has arrived and painted.
      const answered = other.waitForResponse((r) => new URL(r.url()).pathname.endsWith("/api/v1/campaigns"));
      await other.goto("/vi");
      await answered;
      await other.evaluate(() => new Promise((done) => requestAnimationFrame(() => requestAnimationFrame(done))));
      // Prove the page and navbar rendered before asserting absence.
      await expect(other.getByRole("heading", { level: 1 })).toBeVisible();
      await expect(other.getByRole("link", { name: "Blog", exact: true }).first()).toBeVisible();
      await expect(pill(other)).toHaveCount(0);
      await expect(banner(other)).toHaveCount(0);
      expect((await other.locator("nav").first().boundingBox())?.height).toBe(withPill?.height);
      expect(await overflowX(other)).toBeLessThanOrEqual(0);
      await other.close();
    });
  }

  test("switching to English shows EN labels and /en links", async ({ page }) => {
    await stubCms(page);
    await page.goto("/vi");
    await expect(pill(page)).toBeVisible();
    await page.getByRole("button", { name: "Switch to English" }).first().click();
    await expect(page).toHaveURL(/\/en$/);
    await expect(pill(page)).toHaveAttribute("href", "/en/christmas");
    await pill(page).hover();
    const menu = page.getByRole("navigation", { name: "Program menu" });
    await expect(menu.getByRole("link", { name: /US Fulfillment/ })).toHaveAttribute("href", "/en/christmas#san-pham");
    await expect(banner(page).getByRole("link", { name: /Explore Collection/ })).toHaveAttribute("href", "/en/christmas");
  });

  test("/vi/campaigns → detail → CTA → /vi/christmas", async ({ page }) => {
    await stubCms(page);
    await page.goto("/vi/campaigns");
    await page.getByRole("link", { name: /Christmas 2026 Collection/ }).click();
    await expect(page).toHaveURL(/\/vi\/campaigns\/christmas-2026$/);
    await expect(page.getByRole("heading", { level: 1 })).toHaveText("Christmas 2026 Collection");
    await page.getByRole("main").getByRole("link", { name: /Khám phá bộ sưu tập/ }).first().click();
    await expect(page).toHaveURL(/\/vi\/christmas$/);
  });
});

test.describe("phone (375px)", () => {
  test.use({ viewport: { width: 375, height: 812 } });

  for (const fragment of ["%68ot", "%E0%A4%A"]) {
    test(`${fragment}: encoded campaign fragments scroll correctly and malformed fragments do not crash`, async ({ page }) => {
      await stubCms(page);
      const body = structuredClone(golden.list.vi);
      body.campaigns[0].menu_items.find((item: { title: string }) => item.title === "Special Offers").href = `/christmas#${fragment}`;
      await page.route("**/api/v1/campaigns**", (route) => route.fulfill({ json: body }));
      await page.goto("/vi");
      await expect(banner(page)).toBeVisible();
      await page.getByRole("button", { name: "Open menu", exact: true }).click();
      await page.getByRole("region", { name: "Christmas", exact: true }).getByRole("link", { name: /Special Offers/ }).click();
      await expect(page).toHaveURL(new RegExp(`/vi/christmas#${fragment}$`));
      await expect(page.getByRole("heading", { level: 1 })).toContainText("Christmas");
      await expect(page.getByRole("button", { name: "Open menu", exact: true })).toBeVisible();
      if (fragment === "%68ot") {
        await expect.poll(() => page.locator("#hot").evaluate((el) => Math.round(el.getBoundingClientRect().top))).toBe(120);
      }
    });
  }

  test("campaign section links scroll after lazy navigation, within the page and on repeated selection", async ({ page }) => {
    await stubCms(page);
    await page.goto("/vi");
    await expect(banner(page)).toBeVisible();

    const selectSection = async (label: RegExp, id: string) => {
      await page.getByRole("button", { name: "Open menu", exact: true }).click();
      await page.getByRole("region", { name: "Christmas", exact: true }).getByRole("link", { name: label }).click();
      await expect(page).toHaveURL(new RegExp(`/vi/christmas#${id}$`));
      await expect(page.getByRole("button", { name: "Open menu", exact: true })).toBeVisible();
      await expect.poll(() => page.locator(`#${id}`).evaluate((el) => Math.round(el.getBoundingClientRect().top))).toBe(120);
    };

    await selectSection(/Special Offers/, "hot");
    await selectSection(/Fulfill tại Mỹ/, "san-pham");
    await page.evaluate(() => window.scrollTo({ top: 0, behavior: "instant" }));
    await selectSection(/Fulfill tại Mỹ/, "san-pham");
  });

  test("the menu shows the campaign group with prefixed links and no horizontal scroll", async ({ page }) => {
    await stubCms(page);
    await page.goto("/vi");
    await expect(banner(page)).toBeVisible();
    await page.getByRole("button", { name: "Open menu" }).click();
    const group = page.getByRole("region", { name: "Christmas", exact: true });
    await expect(group).toBeVisible();
    await expect(group.getByRole("link", { name: /Special Offers/ })).toHaveAttribute("href", "/vi/christmas#hot");
    expect(await overflowX(page)).toBeLessThanOrEqual(0);
    await group.getByRole("link", { name: /Christmas\s*NEW/ }).click();
    await expect(page).toHaveURL(/\/vi\/christmas$/);
  });
});

test.describe("mobile menu scrolling", () => {
  for (const viewport of [{ width: 320, height: 568 }, { width: 812, height: 375 }, { width: 1023, height: 768 }]) {
    test(`${viewport.width}x${viewport.height}: campaign menu scrolls to the consultation button without moving the page`, async ({ page }) => {
      await page.setViewportSize(viewport);
      await stubCms(page);
      await page.addInitScript(() => localStorage.setItem("thg-consent-v1", "rejected"));
      await page.goto("/vi/christmas");
      await page.getByRole("button", { name: "Open menu", exact: true }).click();
      const group = page.getByRole("region", { name: "Christmas", exact: true });
      await expect(group).toBeVisible();
      const sheet = group.locator("..");
      await sheet.evaluate((el) => { el.scrollTop = el.scrollHeight; });
      await expect.poll(() => sheet.evaluate((el) => el.scrollTop)).toBeGreaterThan(0);
      const consult = page.locator("nav").first().getByRole("button", { name: "Tư vấn ngay", exact: true });
      await expect(consult).toBeInViewport();
      expect(await page.evaluate(() => window.scrollY)).toBe(0);
      expect(await sheet.evaluate((el) => el.scrollWidth - el.clientWidth)).toBe(0);
      await consult.click();
      await expect(page.getByRole("dialog")).toBeVisible();
    });
  }
});
